"""Build the review wall from an actual completed 25-app capture run."""
import pathlib,json,hashlib,html
ROOT=pathlib.Path(__file__).resolve().parents[2];OUT=pathlib.Path(__file__).resolve().parent
report=json.loads((ROOT/'project/evidence/signature-portfolio-browser-checks.json').read_text());apps=json.loads((ROOT/'apps/apps.json').read_text());names={a['id']:a['name']for a in apps}
assert len(report['apps'])==25 and all(a['status']=='passed'for a in report['apps'])
rows=[];cards=[]
for app in report['apps']:
 name=app['app'];file=OUT/(name+'.png');assert file.is_file(),name
 rows.append({'app':name,'file':file.name,'sha256':hashlib.sha256(file.read_bytes()).hexdigest(),'input_sha256':app.get('case_input_sha256'),'scope':app['scope']})
 cards.append('<article><h2>'+html.escape(names[name])+'</h2><p>Workbench · '+html.escape(name)+'</p><a href="'+file.name+'"><img width="390" height="844" loading="lazy" src="'+file.name+'" alt="'+html.escape(names[name])+' actual running workbench"></a></article>')
(OUT/'manifest.json').write_text(json.dumps({'source_commit':report['source_commit'],'checked_at':report['checked_at'],'viewport':report['viewport'],'reduced_motion':report['reduced_motion'],'scope':'Actual Expo Web workbench screens with controlled repository synthetic intake, except the local Nafas screen. No provider inference, current factual/legal acceptance, expert originality approval, physical-device test or release.','screens':rows},indent=2)+'\n')
(OUT/'index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>25 actual workbenches — comparative review</title><style>body{margin:28px;font:16px/1.6 system-ui;background:#13181c;color:#f4f0e6}a{color:#a6dfd2}header{max-width:1040px}main{display:grid;grid-template-columns:repeat(5,390px);gap:30px;align-items:start}article{width:390px}h2{margin-bottom:0;font-size:22px}article p{margin-top:0;color:#ccd4d8}img{display:block;object-fit:contain;border:1px solid #7d868b;border-radius:12px}code{overflow-wrap:anywhere}</style><header><h1>25 real workbench screens, one viewport</h1><p>Actual running Expo Web screens at 390 × 844. Controlled synthetic case input, except local Nafas. These are working interfaces, not proposed mockups. Browser checks do not grant creative approval, verify current law/fees or certify native devices. Repetitive compositions remain redesign work.</p><p><a href="manifest.json">Source revision and capture manifest</a> · <a href="../design-matrix/visual-wall.html">Historical brand and typography wall</a> · <a href="../ui-signatures/index.html">Tested signature interactions</a></p><p>The wide five-column layout deliberately retains identical phone dimensions. Scroll horizontally or zoom out to compare all five columns. Use the image links for full-resolution inspection.</p></header><main>'''+''.join(cards)+'</main></html>')
print('Built 25-screen review wall at source '+report['source_commit'])
